// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    Player player;

    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); player = new Player(c); }

    function testFuzz_property(uint256 delay) public {
        // Lock at the current block; target block is block.number + 1.
        uint256 start = block.number;
        vm.deal(address(player), 1 ether);
        player.lock{value: 1 ether}(keccak256(abi.encodePacked(bytes32(0))));

        // Roll far past the 256-block blockhash window so blockhash(target) == 0
        // and the winning answer is keccak256(abi.encodePacked(bytes32(0))) —
        // exactly the guess the player locked in.
        delay = bound(delay, 300, 1_000_000);
        vm.roll(start + delay);

        player.settle();

        // Rule: a correctly settled winning guess drains the prize; the
        // mutant (no transfer) leaves the contract holding 2 ether.
        assertTrue(address(c).balance == 0);
    }
}

contract Player {
    PredictTheBlockHashChallenge c;
    constructor(PredictTheBlockHashChallenge _c) { c = _c; }
    function lock(bytes32 g) external payable { c.lockInGuess{value: 1 ether}(g); }
    function settle() external { c.settle(); }
    receive() external payable {}
}
